    /* ---- 端末による違い ---- */
    "端末による違い": "不同裝置的差異",
    "ここには二つの道具があります。舞台スケッチは、これから広く使ってもらうためのアプリ。書斎は、資料棚と名簿と制作机を置いた、こちらの手元だけの机です。同じ画面から行き来できますが、配るのは舞台スケッチのほうだけです。":
      "這裡有兩件工具。Stage Sketch是準備讓更多人使用的App；書房則是只屬於我們自己的一張桌子——放著資料架、名冊和寫企劃的書桌。兩者可以在同一個畫面裡來回切換，但對外發送的只有Stage Sketch。",
    "舞台を組み、光を置き、シーンを並べるための道具です。机で組み立て、稽古場へ持ち出し、現場では手元で確かめる——左から右へ、つくるが机に残り、確かめるが手元へ移ります。":
      "這是用來搭舞台、佈光、排場景的工具。在書桌上搭好，帶進排練場，到了現場就在手邊核對——由左至右，「創作」留在桌上，「核對」移到手邊。",
    "舞台を組み、光を置き、シーンを並べるための一枚。これ単独で開けますので、共演者やスタッフへはこちらを渡します。机で組み立て、稽古場へ持ち出し、現場では手元で確かめる——左から右へ、つくるが机に残り、確かめるが手元へ移ります。":
      "用來搭舞台、佈光、排場景的一頁。它可以單獨開啟，交給同台演員和工作人員的就是這一份。在書桌上搭好，帶進排練場，到了現場在手邊核對——由左至右，「創作」留在桌上，「核對」移到手邊。",
    "調べたショーの資料棚、アーティストと制作スタッフの名簿、企画を書く制作机。ここは配りません。舞台スケッチもこの中から使えますが、人へ渡すときは上の単独版のほうを渡します。":
      "查過的演出資料架、藝術家與製作人員的名冊、寫企劃的書桌。這裡不對外發送。Stage Sketch也能從這裡開啟，但交給別人時，請交上面的獨立版。",
