    "ショー全体（シーン・演者・照明・劇場など）を一つのファイルへ書き出して、控えを残します。別の端末へ持っていくときも、このファイルを読み込みます。": "將整個演出（場景、演員、燈光、劇場等）匯出為一個檔案作為備份。帶到其他裝置時，也讀取這個檔案。",
