      "end-stage": "沒有鏡框，舞台與觀眾席同處一個盒子。觀眾在一側，靠階梯地面取得高度。既無側台也無鏡框可遮擋機構，因此要先決定不想被看到的東西放在哪裡。尺寸為暫定值。",
      "gym-stage": "體育館一端的淺舞台。台口寬但進深僅約6米，無法吊掛。觀眾席是平地，後排看不到腳下。舞台高約1.1米，多數沒有側台。尺寸為暫定值，未找到統一規格。",
      "banquet-hall": "在宴會廳搭臨時舞台。舞台約8×4米，天花約4米，無法吊掛，向上拋擲的節目由天花決定。觀眾圍圓桌或站立，沒有作為圍合的觀眾席。柱子、入口以及吊燈下方的留空決定構圖。尺寸為暫定值。",
      "hall-shoebox": "觀眾席呈矩形排列，中央區兩側各有一條通道——日本公共劇場最常見的劃分方式。從兩側區看，舞台是斜的。通道上沒有座位，因此無人從那裡觀看。尺寸與劃分皆為暫定值。",
      "hall-fan": "台口前緣朝觀眾席畫出弧線，觀眾席呈扇形展開——日本公共劇場最常見的形狀。中央區兩側各有一條通道，兩側區比舞台更寬。弧線讓站在中央的演員離觀眾更近；從兩側區看，舞台是斜的。進深含弧線頂點。尺寸與劃分皆為暫定值。",
      "in-the-round": "觀眾席從四周完整圍住表演區。與馬戲帳篷不同，座席為單層，表演圓也更小。沒有正面，站位與朝向必須從每個角度都成立。四個區之間的缺口就是出入口，登場即穿過觀眾席。尺寸為暫定值。",
      "arena-show": "在體育館的演出。舞台設在一端，觀眾席由三面固定看台與鋪在地面的臨時座席組成。加上伸展台，地面座席就被分成左右兩塊：演員能走到觀眾中間，但也會被兩側同時看到。地面座席每場重搭，因此這只是常見的一種佈局，並非標準。尺寸為暫定值。",
      "dome-show": "在巨蛋場館的演出。器形是圓的，觀眾席繞行一周，舞台後方的座位有時也會出售。伸展台佈局把舞台設在一端並伸入觀眾席；中央舞台佈局則在正中搭圓形舞台，面向四周。兩者的地面座席都每場重搭。這只是常見的一種佈局，並非標準。尺寸為暫定值。",
      "kabuki-stage": "歌舞伎的舞台。歌舞伎座公布台口91尺（約27.6公尺）、高21尺（約6.4公尺），舞台中央嵌有直徑60尺（約18.2公尺）的旋轉舞台。花道自下手（觀眾席左側）貫穿觀眾席伸出，長60尺（約18.2公尺）、寬約1.5公尺，與舞台同高，演員就這樣走著上下場。花道的「七三」（距舞台三分、距揚幕七分）設有「すっぽん」升降口，人物由此升出。花道把觀眾席分成兩半，靠外側的席位離花道很近，離舞台卻很遠。上手有時會加設臨時的「仮花道」，但並非常設，此處不做。進深20公尺在歌舞伎座官方頁面上沒有記載，但另一份獨立的行業資料（2013年舞台照明施工案例）予以確認。花道的左右位置與觀眾席進深仍為估值。升降台、二重舞台、定式幕與舞台高度本預設不做。",
      "noh-stage": "能樂堂的舞台。本舞台是京間三間見方（約5.9公尺）的近乎正方形，後方為樂師所在的後座，一側為歌隊所在的地謠座。橋掛從後方一角伸出，演員由此登場（標準為六至七間，11至13公尺）。舞台探入觀眾席，因此正面席與側面席看到的完全不同。本預設不做屋頂、鏡板上的松樹與切戶口。橋掛實際是斜向搭設，此處按直角處理。",
      traverse: "細長的表演帶，兩側被觀眾席夾住。沒有正面：面向一側就等於把背留給另一側，因此靠朝向與移動來經營看法。兩端通常是出入口。觀眾席只有兩塊，既無通道也無正面。尺寸為暫定值。",
