// v0.3.39 release notes.
Object.assign(window.SHOSAI_I18N_PACKS["zh-Hant"].text, {
  "全タブで現在の情報と操作の説明を見られる情報バーを追加しました。ヘッダーから表示を切り替えられます。": "新增資訊列，在所有分頁顯示目前資訊與操作說明。可從頁首切換顯示。",
  "灯体名は通常は短い番号で表示し、選択時やカーソルを合わせたときに名前を出します。機材配置と照明の欄も使いやすくしました。": "燈具平時顯示簡短編號，選取或游標停留時顯示名稱。器材配置與照明面板也更易操作。",
  "シーン操作の入口、劇場設定の入力・削除、選択中の操作欄と文字表示を改善しました。": "改善了場景操作入口、劇場設定的輸入與刪除、所選項目的操作面板和文字顯示。",
  "シーン分割などを元に戻したとき、ほかのシーンの支持台との関連が失われる不具合を修正しました。": "修正還原場景分割等操作時，其他場景的支撐平台關聯遺失的問題。",
  "Mac版に隊形の試作ページとAI用の手引きを同梱しました。保存形式は変わりません。": "Mac版現在隨附隊形試作頁面與AI手引。儲存格式不變。"
});

